using Microsoft.AspNetCore.WebUtilities;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Publicate;
using Xunit;
namespace Publicate.Tests;
public class InstagramUnifiedTests {
 [Theory]
 [InlineData("{\"client_business_id\":\"business\"}",true)]
 [InlineData("{\"id\":\"different-user\",\"client_business_id\":\"business\"}",false)]
 [InlineData("{\"id\":\"system-user\"}",false)]
 public async Task BusinessLookupAcceptsOmittedIdentityButRejectsMismatchAndMissingBusiness(string profile,bool valid){
 var s=AdapterTests.Setup(Platform.Instagram);Configure(s.config);var state=Begin(s.oauth);
 s.handler.Add("{\"access_token\":\"token\"}");s.handler.Add(Debug);s.handler.Add(profile);
 if(valid){s.handler.Add("{\"data\":[{\"id\":\"ig-one\",\"username\":\"one\"}]}");await s.oauth.Complete(Platform.Instagram,state,"code","browser");var account=await s.db.ConnectedAccounts.SingleAsync();Assert.Equal("system-user",account.ExternalId);Assert.Equal("business",account.ClientBusinessId);Assert.Single(await s.db.PublishingTargets.ToListAsync());}
 else{await Assert.ThrowsAsync<ProviderException>(()=>s.oauth.Complete(Platform.Instagram,state,"code","browser"));Assert.Empty(await s.db.ConnectedAccounts.ToListAsync());Assert.Equal(3,s.handler.Requests.Count);}
 Assert.Contains("/me?fields=client_business_id",s.handler.Requests[2]);
 }
 static void Configure(IConfiguration c){c["Providers:Instagram:LoginMode"]="Unified";c["Providers:Instagram:ClientId"]="2082875755677881";c["Providers:Instagram:ConfigId"]="3295601310634577";c["Providers:Instagram:ClientSecret"]="fixture-secret";}
 static string Begin(OAuthService o)=>QueryHelpers.ParseQuery(new Uri(o.Begin(Platform.Instagram,"browser")).Query)["state"].ToString();
 const string Debug="""{"data":{"is_valid":true,"app_id":"2082875755677881","user_id":"system-user","expires_at":0,"scopes":["instagram_basic","instagram_content_publish"],"granular_scopes":[{"scope":"instagram_basic","target_ids":["ig-one","ig-two"]}]}}""";
 [Fact] public void AuthorizationMatchesDashboardAndGeneratesFreshState(){var s=AdapterTests.Setup(Platform.Instagram);Configure(s.config);var uri=new Uri(s.oauth.Begin(Platform.Instagram,"browser"));var q=QueryHelpers.ParseQuery(uri.Query);Assert.Equal("www.facebook.com",uri.Host);Assert.Equal("3295601310634577",q["config_id"]);Assert.Equal("true",q["override_default_response_type"]);Assert.Equal("login",q["prompt"]);Assert.False(q.ContainsKey("scope"));Assert.DoesNotContain("<STATE>",q["state"].ToString());Assert.NotEqual(q["state"].ToString(),Begin(s.oauth));}
 [Fact] public async Task CallbackCreatesOnlyGrantedInstagramTargets(){var s=AdapterTests.Setup(Platform.Instagram);Configure(s.config);var state=Begin(s.oauth);s.handler.Add("{\"access_token\":\"unified-token\"}");s.handler.Add(Debug);s.handler.Add("{\"id\":\"system-user\",\"client_business_id\":\"business\"}");s.handler.Add("{\"data\":[{\"id\":\"ig-one\",\"username\":\"one\"},{\"id\":\"ig-two\",\"username\":\"two\"}]}");await s.oauth.Complete(Platform.Instagram,state,"code","browser");var a=await s.db.ConnectedAccounts.SingleAsync();Assert.True(OAuthService.IsUnified(a));Assert.Null(a.ExpiresAt);Assert.Equal("business",a.ClientBusinessId);var targets=await s.db.PublishingTargets.ToListAsync();Assert.Equal(2,targets.Count);Assert.All(targets,t=>{Assert.Equal(Platform.Instagram,t.Platform);Assert.Equal("InstagramUnified",t.Kind);Assert.Null(t.AccessToken);});Assert.Contains("/oauth/access_token",s.handler.Requests[0]);Assert.All(s.handler.Requests,r=>Assert.Contains("graph.facebook.com",r));Assert.DoesNotContain(s.handler.Requests,r=>r.Contains("/me/accounts"));await Assert.ThrowsAsync<InvalidOperationException>(()=>s.oauth.Complete(Platform.Instagram,state,"code","browser"));}
 [Fact] public async Task TokenForOtherAppCannotBeSaved(){var s=AdapterTests.Setup(Platform.Instagram);Configure(s.config);var state=Begin(s.oauth);s.handler.Add("{\"access_token\":\"token\"}");s.handler.Add(Debug.Replace("2082875755677881","wrong-app"));await Assert.ThrowsAsync<ProviderException>(()=>s.oauth.Complete(Platform.Instagram,state,"code","browser"));Assert.Empty(await s.db.ConnectedAccounts.ToListAsync());}
 [Fact] public async Task EmptyAssignedAccountsCannotInventTargets(){var s=AdapterTests.Setup(Platform.Instagram);Configure(s.config);var state=Begin(s.oauth);s.handler.Add("{\"access_token\":\"token\"}");s.handler.Add(Debug);s.handler.Add("{\"id\":\"system-user\",\"client_business_id\":\"business\"}");s.handler.Add("{\"data\":[]}");var e=await Assert.ThrowsAsync<ProviderException>(()=>s.oauth.Complete(Platform.Instagram,state,"code","browser"));Assert.Equal(JobState.RequiresApproval,e.Result.State);Assert.Empty(await s.db.PublishingTargets.ToListAsync());}
 [Fact] public async Task ModeChangeDuringOAuthIsRejectedBeforeTokenExchange(){var s=AdapterTests.Setup(Platform.Instagram);Configure(s.config);var state=Begin(s.oauth);s.config["Providers:Instagram:LoginMode"]="Direct";await Assert.ThrowsAsync<InvalidOperationException>(()=>s.oauth.Complete(Platform.Instagram,state,"code","browser"));Assert.Empty(s.handler.Requests);}
 [Fact] public async Task UnifiedPublishingUsesFacebookGraphEvenIfDefaultModeChanges(){var s=AdapterTests.Setup(Platform.Instagram);s.target.Account.AuthMethod="InstagramUnified";s.target.Kind="InstagramUnified";s.handler.Add("{\"id\":\"container\"}");s.handler.Add("{\"status_code\":\"FINISHED\"}");s.handler.Add("{\"id\":\"post\"}");var result=await new InstagramPublisher(s.http,s.oauth,s.storage).PublishPost(AdapterTests.Context(s.target,new MediaAsset{ContentType="image/jpeg",PublicUrl="https://example.test/a.jpg"}),default);Assert.Equal(JobState.Published,result.State);Assert.All(s.handler.Requests,r=>Assert.Contains("graph.facebook.com/v25.0/",r));}
 [Fact] public async Task UnifiedRefreshNeverUsesInstagramRefreshEndpoint(){var s=AdapterTests.Setup(Platform.Instagram);Configure(s.config);s.target.Account.AuthMethod="InstagramUnified";await Assert.ThrowsAsync<ProviderException>(()=>s.oauth.Refresh(s.target.Account));Assert.Empty(s.handler.Requests);}
 [Theory][InlineData(false)][InlineData(true)] public async Task ValidationDoesNotRequirePageToken(bool unified){var s=AdapterTests.Setup(Platform.Instagram);if(unified){s.target.Account.AuthMethod="InstagramUnified";s.target.Account.Scopes="instagram_basic instagram_content_publish";s.target.Kind="InstagramUnified";}var v=new PostVariant{Post=new(),Target=s.target};var errors=await new PublicationService(s.db,[],s.storage,s.config).Validate(v);Assert.DoesNotContain(errors,e=>e.Contains("tokenu celu")||e.Contains("scope:"));}
}
